{
  "id": "sales-report-message",
  "name": "Sales Report Message",
  "description": "Renders app.sales.report custom events as a sortable monthly revenue table inside chat messages.",
  "version": "0.0.1",
  "capabilities": [
    "sales-report-message"
  ],
  "data": {
    "messageUI": true
  },
  "authoring": {
    "intents": [
      "显示月度销售报表表格",
      "在聊天消息里显示报表",
      "按收入排序查看每月订单数量",
      "render sales report table in chat"
    ],
    "visualRole": "chat message renderer for the app.sales.report custom event"
  }
}

import { z } from "zod";

/** Name of the Agent `CUSTOM` event that carries the report envelope. */
export const SALES_REPORT_EVENT_NAME = "app.sales.report";

/**
 * The Agent sends `{ format: "json", payload: "<json string>" }` as the event
 * value. The runtime uses this schema only to recognize the event name as an app
 * event; the renderer performs the strict decoding itself so an unexpected but
 * real payload still reaches the message instead of being dropped silently.
 */
export const salesReportEventSchema = z.unknown();

export type SalesReportRow = {
  month: string;
  revenue: number;
  orderCount: number;
};

export type SalesReportData = {
  title?: string;
  rows: SalesReportRow[];
};

function parseJsonText(value: string): unknown {
  const text = value.trim();
  if (text === "") {
    return undefined;
  }
  try {
    return JSON.parse(text) as unknown;
  } catch {
    return undefined;
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function toFiniteNumber(value: unknown): number | null {
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : null;
  }
  if (typeof value === "string" && value.trim() !== "") {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : null;
  }
  return null;
}

/**
 * Unwraps the shapes the report can arrive in: the `{format, payload}` envelope,
 * an already decoded `{title, rows}` object, or the raw JSON text.
 */
function unwrapReportSource(input: unknown, depth = 0): unknown {
  if (depth > 4) {
    return undefined;
  }
  if (typeof input === "string") {
    return parseJsonText(input);
  }
  if (!isRecord(input)) {
    return undefined;
  }
  if ("payload" in input) {
    const payload = input.payload;
    if (typeof payload === "string") {
      return parseJsonText(payload);
    }
    if (isRecord(payload) || Array.isArray(payload)) {
      return payload;
    }
    return undefined;
  }
  if ("rows" in input) {
    return input;
  }
  if ("value" in input) {
    return unwrapReportSource(input.value, depth + 1);
  }
  if ("data" in input) {
    return unwrapReportSource(input.data, depth + 1);
  }
  return undefined;
}

function normalizeRow(input: unknown): SalesReportRow | null {
  if (!isRecord(input)) {
    return null;
  }
  const month = typeof input.month === "string" ? input.month.trim() : "";
  if (month === "") {
    return null;
  }
  const revenue = toFiniteNumber(input.revenue);
  const orderCount = toFiniteNumber(input.order_count ?? input.orderCount);
  if (revenue === null || orderCount === null) {
    return null;
  }
  return { month, revenue, orderCount };
}

/** Returns the decoded report, or `null` when the payload is not a usable report. */
export function parseSalesReport(input: unknown): SalesReportData | null {
  const candidate = unwrapReportSource(input);
  if (!isRecord(candidate) || !Array.isArray(candidate.rows)) {
    return null;
  }

  const rows: SalesReportRow[] = [];
  for (const item of candidate.rows) {
    const row = normalizeRow(item);
    if (row) {
      rows.push(row);
    }
  }
  if (rows.length === 0 && candidate.rows.length > 0) {
    return null;
  }

  const title = typeof candidate.title === "string" ? candidate.title.trim() : "";
  return { title: title === "" ? undefined : title, rows };
}

import { useAgentUILocaleCode } from "@za38.03/agent-ui-plugins";
import { useMemo, useState } from "react";
import { parseSalesReport } from "./schema";
import "./styles.css";

type SalesReportMessageProps = {
  data?: unknown;
};

type SalesReportLocaleText = {
  fallbackTitle: string;
  month: string;
  revenue: string;
  sortDescending: string;
  sortAscending: string;
  empty: string;
  invalid: string;
  detailHint: string;
  detail: (month: string, orderCount: string) => string;
};

const messages: Record<string, SalesReportLocaleText> = {
  "zh-CN": {
    fallbackTitle: "销售报表",
    month: "月份",
    revenue: "收入",
    sortDescending: "收入从高到低",
    sortAscending: "收入从低到高",
    empty: "报表中没有可显示的数据行。",
    invalid: "无法解析这条报表数据，暂时无法显示表格。",
    detailHint: "点击任意一行查看该月的订单数量。",
    detail: (month, orderCount) => `${month} 的订单数量：${orderCount}`,
  },
  "en-US": {
    fallbackTitle: "Sales report",
    month: "Month",
    revenue: "Revenue",
    sortDescending: "Revenue high to low",
    sortAscending: "Revenue low to high",
    empty: "The report has no rows to display.",
    invalid: "This report data could not be parsed, so the table cannot be shown.",
    detailHint: "Select a row to see that month's order count.",
    detail: (month, orderCount) => `${month} order count: ${orderCount}`,
  },
};

type SortDirection = "desc" | "asc";

export function SalesReportMessagePlugin(props: SalesReportMessageProps) {
  const localeCode = useAgentUILocaleCode();
  const text = messages[localeCode] ?? messages["zh-CN"]!;
  const report = useMemo(() => parseSalesReport(props.data), [props.data]);
  const [direction, setDirection] = useState<SortDirection>("desc");
  const [selectedKey, setSelectedKey] = useState<string | null>(null);

  const orderedRows = useMemo(() => {
    if (!report) {
      return [];
    }
    return report.rows
      .map((row, index) => ({ key: `${row.month}#${index}`, row }))
      .sort((left, right) =>
        direction === "desc"
          ? right.row.revenue - left.row.revenue
          : left.row.revenue - right.row.revenue,
      );
  }, [report, direction]);

  const formatNumber = (value: number) =>
    new Intl.NumberFormat(localeCode === "en-US" ? "en-US" : "zh-CN", {
      maximumFractionDigits: 0,
    }).format(value);

  if (!report) {
    return (
      <div className="sales-report sales-report--invalid" role="status">
        <p className="sales-report__invalid-text">{text.invalid}</p>
      </div>
    );
  }

  const selected = orderedRows.find((entry) => entry.key === selectedKey) ?? null;
  const sortLabel = direction === "desc" ? text.sortDescending : text.sortAscending;
  const selectRow = (key: string) => {
    setSelectedKey((current) => (current === key ? null : key));
  };

  return (
    <section className="sales-report" aria-label={report.title ?? text.fallbackTitle}>
      <h3 className="sales-report__title">{report.title ?? text.fallbackTitle}</h3>
      <div className="sales-report__table-wrap">
        <table className="sales-report__table">
          <thead>
            <tr>
              <th scope="col" className="sales-report__head-cell">
                {text.month}
              </th>
              <th
                scope="col"
                className="sales-report__head-cell sales-report__head-cell--revenue"
                aria-sort={direction === "desc" ? "descending" : "ascending"}
              >
                <button
                  type="button"
                  className="sales-report__sort"
                  aria-label={`${text.revenue}：${sortLabel}`}
                  onClick={() =>
                    setDirection((current) => (current === "desc" ? "asc" : "desc"))
                  }
                >
                  <span>{text.revenue}</span>
                  <span aria-hidden="true">{direction === "desc" ? "↓" : "↑"}</span>
                </button>
              </th>
            </tr>
          </thead>
          <tbody>
            {orderedRows.length === 0 ? (
              <tr>
                <td className="sales-report__empty" colSpan={2}>
                  {text.empty}
                </td>
              </tr>
            ) : (
              orderedRows.map((entry) => {
                const isSelected = entry.key === selectedKey;
                return (
                  <tr
                    key={entry.key}
                    className="sales-report__row"
                    data-selected={isSelected ? "true" : "false"}
                    tabIndex={0}
                    aria-selected={isSelected}
                    onClick={() => selectRow(entry.key)}
                    onKeyDown={(event) => {
                      if (event.key === "Enter" || event.key === " ") {
                        event.preventDefault();
                        selectRow(entry.key);
                      }
                    }}
                  >
                    <th scope="row" className="sales-report__month">
                      {entry.row.month}
                    </th>
                    <td className="sales-report__revenue">{formatNumber(entry.row.revenue)}</td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>
      <div
        className="sales-report__detail"
        role="status"
        aria-live="polite"
        data-empty={selected ? "false" : "true"}
      >
        {selected
          ? text.detail(selected.row.month, formatNumber(selected.row.orderCount))
          : text.detailHint}
      </div>
    </section>
  );
}

import type { UIPluginDefinition, UIPluginManifest } from "@za38.03/agent-ui-plugins";
import { defineDataMessageUI } from "@za38.03/agent-ui-plugins";
import manifestJson from "./manifest.json";
import { SalesReportMessagePlugin } from "./index";

const definition: UIPluginDefinition = {
  manifest: manifestJson as UIPluginManifest,
  provides: [],
  inject: [],
  optionalInject: ["agent-ui.locale"],
  dataMessageUIs: [
    defineDataMessageUI<unknown>({
      name: "app.sales.report",
      render: SalesReportMessagePlugin,
    }),
  ],
  Component: () => null,
};

export default definition;

.sales-report {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--card);
  color: var(--foreground);
  font-size: 13px;
  line-height: 1.5;
}

.sales-report__title {
  margin: 0 0 8px;
  font-size: 14px;
  font-weight: 600;
  overflow-wrap: anywhere;
}

.sales-report__table-wrap {
  min-width: 0;
  overflow-x: auto;
}

.sales-report__table {
  width: 100%;
  border-collapse: collapse;
  font-variant-numeric: tabular-nums;
}

.sales-report__table th,
.sales-report__table td {
  padding: 6px 8px;
  text-align: left;
  white-space: nowrap;
  border-bottom: 1px solid var(--border);
}

.sales-report__table tbody tr:last-child th,
.sales-report__table tbody tr:last-child td {
  border-bottom: none;
}

.sales-report__head-cell {
  font-size: 12px;
  font-weight: 600;
  opacity: 0.75;
}

.sales-report__head-cell--revenue {
  text-align: right;
}

.sales-report__sort {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin: 0;
  padding: 2px 4px;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}

.sales-report__sort:hover {
  background: var(--muted);
}

.sales-report__sort:focus-visible {
  outline: 2px solid var(--ring, var(--border));
  outline-offset: 2px;
}

.sales-report__row {
  cursor: pointer;
}

.sales-report__row:hover {
  background: var(--muted);
}

.sales-report__row:focus-visible {
  outline: 2px solid var(--ring, var(--border));
  outline-offset: -2px;
}

.sales-report__row[data-selected="true"] {
  background: var(--muted);
}

.sales-report__month {
  font-weight: 500;
  text-align: left;
}

.sales-report__row[data-selected="true"] .sales-report__month {
  font-weight: 600;
}

.sales-report__revenue {
  text-align: right;
}

.sales-report__detail {
  margin-top: 8px;
  padding: 6px 8px;
  border-radius: 8px;
  background: var(--muted);
  font-size: 13px;
  overflow-wrap: anywhere;
}

.sales-report__detail[data-empty="true"] {
  padding-left: 0;
  background: transparent;
  font-size: 12px;
  opacity: 0.7;
}

.sales-report__empty {
  padding: 8px;
  text-align: center;
  opacity: 0.7;
}

.sales-report--invalid {
  border-style: dashed;
}

.sales-report__invalid-text {
  margin: 0;
  font-size: 13px;
  overflow-wrap: anywhere;
}

@media (max-width: 480px) {
  .sales-report {
    padding: 10px;
  }

  .sales-report__table th,
  .sales-report__table td {
    padding: 6px;
  }
}

